import Foundation

/// Context required to exchange a FairPlay Streaming content key.
///
/// The SPC is generated by AVFoundation for this request. The CKC returned by
/// the license provider is passed back to AVFoundation without being stored
/// or exposed in playback snapshots.
public struct FairPlayLicenseRequest: Sendable {
    public let contentIdentifier: Data
    public let streamingContentKeyRequest: Data
    public let isRenewal: Bool

    public init(
        contentIdentifier: Data,
        streamingContentKeyRequest: Data,
        isRenewal: Bool
    ) {
        self.contentIdentifier = contentIdentifier
        self.streamingContentKeyRequest = streamingContentKeyRequest
        self.isRenewal = isRenewal
    }
}

/// App-owned FairPlay certificate and license-server integration.
///
/// Content identifiers and license request/response formats differ between
/// providers. Implement this protocol in the host app; never embed a FairPlay
/// private key or license-server secret in the StreamKit package. Implementations
/// should honor task cancellation and must not log certificates, SPCs, or CKCs.
public protocol FairPlayLicenseProvider: Sendable {
    /// Returns the FairPlay application certificate bytes issued for the app.
    func applicationCertificate() async throws -> Data

    /// Converts AVFoundation's key URI into the provider's content identifier.
    func contentIdentifier(
        for keyIdentifier: String,
        initializationData: Data?
    ) throws -> Data

    /// Exchanges the SPC for a CKC. Return the raw CKC bytes expected by
    /// `AVContentKeyResponse`; unwrap provider-specific response envelopes here.
    func contentKey(for request: FairPlayLicenseRequest) async throws -> Data
}

/// Safe lifecycle diagnostics emitted by AVFoundation's FairPlay key session.
/// These values intentionally omit key identifiers and DRM payload data.
public enum FairPlayKeySessionDiagnostic: Equatable, Sendable {
    /// AVFoundation successfully processed the supplied content-key response.
    case contentKeyResponseAccepted
    /// AVFoundation reported that it couldn't process a content-key request.
    case contentKeyRequestFailed(errorDomain: String, errorCode: Int)

    public var message: String {
        switch self {
        case .contentKeyResponseAccepted:
            "AVFoundation accepted the FairPlay content-key response."
        case let .contentKeyRequestFailed(domain, code):
            "AVFoundation reported a FairPlay key-request failure (\(domain), code \(code))."
        }
    }
}

/// Configuration for FairPlay Streaming key acquisition.
public struct FairPlayConfiguration: Sendable, Equatable {
    private let id: UUID
    let licenseProvider: any FairPlayLicenseProvider
    let diagnosticHandler: (@Sendable (FairPlayKeySessionDiagnostic) -> Void)?

    public init(
        licenseProvider: any FairPlayLicenseProvider,
        diagnosticHandler: (@Sendable (FairPlayKeySessionDiagnostic) -> Void)? = nil
    ) {
        self.id = UUID()
        self.licenseProvider = licenseProvider
        self.diagnosticHandler = diagnosticHandler
    }

    public static func == (lhs: Self, rhs: Self) -> Bool {
        lhs.id == rhs.id
    }
}

/// Supplies a fresh bearer token for each media resource request.
///
/// The player invokes the provider for the initial asset and each HLS child
/// resource. Exact host allowlisting prevents credentials from being sent to
/// hosts that are not explicitly trusted.
public struct MediaBearerAuthentication: Sendable, Equatable {
    private let id: UUID
    private let trustedHosts: Set<String>
    private let tokenProvider: @Sendable (URL) async throws -> String

    /// Creates bearer authentication scoped to an explicit set of host names.
    /// Host names are compared case-insensitively and must match exactly.
    public init(
        trustedHosts: Set<String>,
        tokenProvider: @escaping @Sendable (URL) async throws -> String
    ) {
        self.id = UUID()
        self.trustedHosts = Set(trustedHosts.map { $0.lowercased() })
        self.tokenProvider = tokenProvider
    }

    func token(for url: URL) async throws -> String? {
        guard url.scheme?.lowercased() == "https",
              let host = url.host?.lowercased(),
              trustedHosts.contains(host)
        else {
            return nil
        }
        do {
            let token = try await tokenProvider(url)
            try Task.checkCancellation()
            guard !token.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
                throw PlaybackFailure(
                    code: .authentication,
                    message: "The media token provider returned an empty token."
                )
            }
            return token
        } catch is CancellationError {
            throw CancellationError()
        } catch let failure as PlaybackFailure {
            throw failure
        } catch {
            throw PlaybackFailure(
                code: .authentication,
                message: "The app could not obtain media authorization."
            )
        }
    }

    func authorizationHeader(for url: URL) async throws -> String? {
        try await token(for: url).map { "Bearer \($0)" }
    }

    func trusts(_ url: URL) -> Bool {
        guard url.scheme?.lowercased() == "https",
              let host = url.host?.lowercased()
        else { return false }
        return trustedHosts.contains(host)
    }

    public static func == (lhs: Self, rhs: Self) -> Bool {
        lhs.id == rhs.id
    }
}

/// A cookie attached to matching media requests made by AVFoundation.
public struct MediaCookie: Equatable, Sendable {
    public let name: String
    public let value: String
    public let domain: String
    public let path: String
    public let isSecure: Bool

    public init(
        name: String,
        value: String,
        domain: String,
        path: String = "/",
        isSecure: Bool = true
    ) {
        self.name = name
        self.value = value
        self.domain = domain
        self.path = path
        self.isSecure = isSecure
    }
}

/// Configuration for requests used to retrieve media.
public struct MediaRequestConfiguration: Equatable, Sendable {

    /// Cookies scoped by domain and path for media requests.
    /// Authenticated loading uses only these explicit cookies and does not
    /// consult the app's shared URLSession cookie storage.
    public let cookies: [MediaCookie]
    /// User-Agent supplied to AVURLAsset for media requests.
    public let userAgent: String?
    /// Optional bearer authentication for explicitly trusted media hosts.
    public let bearerAuthentication: MediaBearerAuthentication?
    /// Optional FairPlay Streaming integration for protected HLS media.
    public let fairPlay: FairPlayConfiguration?

    public init(
        cookies: [MediaCookie] = [],
        userAgent: String? = nil,
        bearerAuthentication: MediaBearerAuthentication? = nil,
        fairPlay: FairPlayConfiguration? = nil
    ) {
        self.cookies = cookies
        self.userAgent = userAgent
        self.bearerAuthentication = bearerAuthentication
        self.fairPlay = fairPlay
    }

    public static func == (lhs: Self, rhs: Self) -> Bool {
        lhs.cookies == rhs.cookies
            && lhs.userAgent == rhs.userAgent
            && lhs.bearerAuthentication == rhs.bearerAuthentication
            && lhs.fairPlay == rhs.fairPlay
    }
}

/// Declares the presentation semantics supplied by the media provider.
public enum MediaPresentationKind: Equatable, Sendable {
    /// No live or on-demand classification was supplied.
    case unspecified
    /// Finite, on-demand media such as a VOD asset.
    case onDemand
    /// A live presentation, with DVR availability reported by seekable ranges.
    case live
}

/// Describes a media resource that StreamKit can play.
public struct MediaSource: Equatable, Sendable {

    /// The location of the media resource.
    public let url: URL

    /// Configuration used when requesting the media.
    public let requestConfiguration: MediaRequestConfiguration
    /// Caller-supplied playback semantics. StreamKit doesn't infer live
    /// playback from an indefinite duration or seekable ranges.
    public let presentationKind: MediaPresentationKind

    public init(
        url: URL,
        requestConfiguration: MediaRequestConfiguration = .init(),
        presentationKind: MediaPresentationKind = .unspecified
    ) {
        self.url = url
        self.requestConfiguration = requestConfiguration
        self.presentationKind = presentationKind
    }
}
